    @Test void publicationCreatesImmutableIntentAndRefusesSameSliceReplay()throws Exception{
        var cfg=config(temp);var original=preview(cfg,true,true);Path preview=temp.resolve("original-preview.json");byte[] source=JobDefinitionJson.mapper().writeValueAsBytes(original);Files.write(preview,source);
        var expected=gateway().parsePreview(original,DAY,original.path("invocation_id").asText(),preview,EtfMarketOverviewCacheOwnerGateway.sha(source));
        var launches=new java.util.concurrent.atomic.AtomicInteger();Process process=mockProcess(true);
        EtfMarketOverviewCacheOwnerGateway.ProcessLauncher launch=(args,log)->{launches.incrementAndGet();var request=JobDefinitionJson.mapper().readTree(Files.readAllBytes(Path.of(args.get(4))));var output=original.deepCopy();output.put("operation","publish");output.put("status","VERIFIED_READTHROUGH");output.put("invocation_id",request.path("invocation_id").asText());output.put("owner_invoked",true);output.put("owner_sender_stopped",true);output.put("exact_owner_digest_verified",true);output.put("source_unchanged",true);output.put("actual_owner_hits",1);output.put("actual_owner_misses",0);output.set("actual_cache_records",original.get("expected_cache_records"));output.set("actual_receipt",original.get("expected_receipt"));output.set("source_snapshots_after",original.get("source_snapshots"));output.set("target_snapshots_after",original.get("target_snapshots"));output.set("target_actual_row_counts_after",original.get("target_actual_row_counts"));output.putArray("owner_submissions");output.put("cache_key_absent_after",false);Files.write(Path.of(args.get(6)),JobDefinitionJson.mapper().writeValueAsBytes(output),StandardOpenOption.CREATE_NEW);return process;};
        var gateway=new EtfMarketOverviewCacheOwnerGateway(cfg,launch){@Override protected void requireConfigured(){}@Override public void validateSubmission(EtfMarketOverviewCachePublicationEnvelope row,VerifiedBatchExecutor.Submission submission){}};
        var submission=new VerifiedBatchExecutor.Submission(temp.resolve("ledger.sqlite"),"run1","slice1",4,UNIT);var result=gateway.publish(expected,submission,()->false);assertTrue(result.processStopped());assertTrue(Files.isRegularFile(result.intentPath()));assertTrue(gateway.writerStopped(submission.ledgerPath(),"run1"));assertThrows(IllegalStateException.class,()->gateway.publish(expected,submission,()->false));assertEquals(1,launches.get());
    }
    @Test void timeoutKillsThenWaitsForExitAndRetainsUnknownIntentWithoutRetry()throws Exception{
        var cfg=config(temp);var original=preview(cfg,true,true);Path path=temp.resolve("original.json");byte[] bytes=JobDefinitionJson.mapper().writeValueAsBytes(original);Files.write(path,bytes);var expected=gateway().parsePreview(original,DAY,original.path("invocation_id").asText(),path,EtfMarketOverviewCacheOwnerGateway.sha(bytes));
        Process process=mockProcess(false);when(process.waitFor(anyLong(),eq(TimeUnit.NANOSECONDS))).thenReturn(true);var launches=new java.util.concurrent.atomic.AtomicInteger();
        var gateway=new EtfMarketOverviewCacheOwnerGateway(cfg,(args,log)->{launches.incrementAndGet();return process;}){@Override protected void requireConfigured(){}@Override public void validateSubmission(EtfMarketOverviewCachePublicationEnvelope row,VerifiedBatchExecutor.Submission submission){}};
        var submission=new VerifiedBatchExecutor.Submission(temp.resolve("ledger.sqlite"),"run1","slice1",4,UNIT);assertThrows(IllegalStateException.class,()->gateway.publish(expected,submission,()->true));
        // Cancellation before launch has no owner boundary and no intent.
        assertEquals(0,launches.get());
        var cancellation=new java.util.concurrent.atomic.AtomicInteger();assertThrows(IOException.class,()->gateway.publish(expected,submission,()->cancellation.incrementAndGet()>1));
        verify(process).destroyForcibly();verify(process).waitFor(anyLong(),eq(TimeUnit.NANOSECONDS));assertTrue(gateway.writerStopped(submission.ledgerPath(),"run1"));assertThrows(IllegalStateException.class,()->gateway.publish(expected,submission,()->false));assertEquals(1,launches.get());
    }
    @Test void atomicClaimAllowsOnlyOneOfTwoGatewayInstancesForSameDurableSlice()throws Exception{
        var cfg=config(temp);var original=preview(cfg,true,true);Path path=temp.resolve("race-original.json");byte[] bytes=JobDefinitionJson.mapper().writeValueAsBytes(original);Files.write(path,bytes);var expected=gateway().parsePreview(original,DAY,original.path("invocation_id").asText(),path,EtfMarketOverviewCacheOwnerGateway.sha(bytes));
        var barrier=new java.util.concurrent.CyclicBarrier(2);var launches=new java.util.concurrent.atomic.AtomicInteger();Process process=mockProcess(true);
        EtfMarketOverviewCacheOwnerGateway.ProcessLauncher launch=(args,log)->{launches.incrementAndGet();var request=JobDefinitionJson.mapper().readTree(Files.readAllBytes(Path.of(args.get(4))));var output=original.deepCopy();output.put("operation","publish");output.put("status","VERIFIED_READTHROUGH");output.put("invocation_id",request.path("invocation_id").asText());output.put("owner_invoked",true);output.put("owner_sender_stopped",true);output.put("exact_owner_digest_verified",true);output.put("source_unchanged",true);output.put("actual_owner_hits",1);output.put("actual_owner_misses",0);output.set("actual_cache_records",original.get("expected_cache_records"));output.set("actual_receipt",original.get("expected_receipt"));output.set("source_snapshots_after",original.get("source_snapshots"));output.set("target_snapshots_after",original.get("target_snapshots"));output.set("target_actual_row_counts_after",original.get("target_actual_row_counts"));output.putArray("owner_submissions");output.put("cache_key_absent_after",false);Files.write(Path.of(args.get(6)),JobDefinitionJson.mapper().writeValueAsBytes(output),StandardOpenOption.CREATE_NEW);return process;};
        class RacingGateway extends EtfMarketOverviewCacheOwnerGateway {
            RacingGateway(){super(cfg,launch);}
            @Override protected void requireConfigured(){}
            @Override public void validateSubmission(EtfMarketOverviewCachePublicationEnvelope row,VerifiedBatchExecutor.Submission submission){}
            @Override public EtfMarketOverviewCachePublicationEnvelope parsePreview(com.fasterxml.jackson.databind.JsonNode node,LocalDate day,String invocation,Path artifact,String digest)throws IOException{
                try{barrier.await(3,TimeUnit.SECONDS);}catch(Exception error){throw new IOException(error);}return super.parsePreview(node,day,invocation,artifact,digest);
            }
        }
        var first=new RacingGateway();var second=new RacingGateway();var submission=new VerifiedBatchExecutor.Submission(temp.resolve("ledger.sqlite"),"run1","slice1",4,UNIT);
        try(var workers=java.util.concurrent.Executors.newFixedThreadPool(2)){
            var calls=List.of(workers.submit(()->{try{return first.publish(expected,submission,()->false).status();}catch(IllegalStateException claimed){return "CLAIM_REJECTED";}}),workers.submit(()->{try{return second.publish(expected,submission,()->false).status();}catch(IllegalStateException claimed){return "CLAIM_REJECTED";}}));
            var outcomes=new HashSet<String>();for(var call:calls)outcomes.add(call.get(5,TimeUnit.SECONDS));assertEquals(Set.of("VERIFIED_READTHROUGH","CLAIM_REJECTED"),outcomes);
        }
        assertEquals(1,launches.get());assertTrue(first.writerStopped(submission.ledgerPath(),"run1"));try(var claims=Files.list(temp.resolve("d101-owner-intent-claims"))){assertEquals(1,claims.count());}
    }
