    @Test void nullTargetRejectsMissingCountBooleanCountRawRowsOrWalNonzero(){
        for(String bad:List.of("missing_count","boolean_count","nonzero_count","missing_raw_rows","nonzero_raw_rows","wal")){
            var value=preview(config(temp),true,true);String table=EtfMarketOverviewCachePublicationEnvelope.CACHE;var row=(ObjectNode)value.path("target_snapshots").path(table);var p=(ObjectNode)row.get("physical");var w=(ObjectNode)row.get("wal");p.putNull("table_txn").putNull("table_row_count");w.put("sequencerTxn",0).put("writerTxn",0);var counts=(ObjectNode)value.get("target_actual_row_counts");counts.put(table,0);
            switch(bad){case "missing_count"->counts.remove(table);case "boolean_count"->counts.put(table,false);case "nonzero_count"->counts.put(table,1);case "missing_raw_rows"->p.remove("table_row_count");case "nonzero_raw_rows"->p.put("table_row_count",1);case "wal"->{w.put("sequencerTxn",1);w.put("writerTxn",1);}}
            assertThrows(IOException.class,()->parse(value),bad);
        }
    }
