    @Test void actualSQLiteParentCancellationAndReadonlyReconcileModeFailBeforeProcessLaunch()throws Exception{
        Path directory=Files.createTempDirectory(Path.of("var"),"d101-gateway-unit-");
        try{
            var expected=parse(preview(config(temp),true,true));var ledger=new com.zoutrankil.data.repository.SyncRunLedger(directory.resolve("ledger.sqlite"));
            var parameters=Map.<String,Object>of("source_version",SOURCE,"target_id",TARGET,"bootstrap_from",DAY);
            var request=EtfMarketOverviewDailyCacheJobService.definition().freeze(SyncJobDefinition.Mode.MATERIALIZE,parameters,DAY,DAY,DAY);
            ledger.createRun("grandparent",null,TARGET,request);ledger.createRun("parent","grandparent",TARGET,request);ledger.createRun("child","parent",TARGET,request);
            submitted(ledger,"child",expected);var context=new VerifiedBatchExecutor.Submission(ledger.path(),"child","child-slice",4,UNIT);gateway().validateSubmission(expected,context);
            ledger.requestCancellation("grandparent");assertThrows(IllegalStateException.class,()->gateway().validateSubmission(expected,context));
            var readonly=EtfMarketOverviewDailyCacheJobService.definition().freeze(SyncJobDefinition.Mode.RECONCILE,parameters,DAY,DAY,DAY);ledger.createRun("readonly",null,TARGET,readonly);submitted(ledger,"readonly",expected);
            assertThrows(IllegalStateException.class,()->gateway().validateSubmission(expected,new VerifiedBatchExecutor.Submission(ledger.path(),"readonly","readonly-slice",4,UNIT)));
        }finally{try(var paths=Files.walk(directory)){for(Path file:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(file);}}
    }
    private static void submitted(com.zoutrankil.data.repository.SyncRunLedger ledger,String run,EtfMarketOverviewCachePublicationEnvelope expected)throws Exception{
        ledger.transition(run,0,SyncRunState.RUNNING,"{}");ledger.createChild(run+"-attempt",com.zoutrankil.data.repository.SyncRunLedger.Kind.ATTEMPT,run,run);ledger.transition(run+"-attempt",0,SyncRunState.RUNNING,"{}");ledger.createChild(run+"-slice",com.zoutrankil.data.repository.SyncRunLedger.Kind.SLICE,run,run+"-attempt");ledger.transition(run+"-slice",0,SyncRunState.RUNNING,"{}");
        String payload=JobDefinitionJson.mapper().writeValueAsString(Map.of("returnedRows",1,"sourceFingerprint",UNIT,"responseEvidence",expected.responseEvidence()));
        ledger.transition(run+"-slice",1,SyncRunState.FETCHED,payload);ledger.transition(run+"-slice",2,SyncRunState.VALIDATED,payload);ledger.transition(run+"-slice",3,SyncRunState.SUBMITTED,payload);
    }
